spec.rawSql:
-- Single detections, read on the server from the mirror's yearly files, once
-- the map is zoomed in to a view under 25 degrees across: the window's years
-- only, and in each file only the row groups whose box meets the view (the
-- rows are sorted along a Hilbert curve, so a view of a few degrees reads a
-- handful of the five hundred groups of a year; ST_Intersects_Extent is what
-- lets DuckDB skip them). The strongest 100,000 by FRP when there are more.
-- Wider than that, it opens only the small file of 2000 and returns nothing.
-- The time is a label, not a timestamp, so kepler hangs no time filter on it.
-- Country and months follow the A5 cells only; the window and the view, this.
SET parquet_metadata_cache = true;
SET VARIABLE w = greatest(coalesce(try_cast($w AS DOUBLE), -180), -180);
SET VARIABLE e = least(coalesce(try_cast($e AS DOUBLE), 180), 180);
SET VARIABLE s = greatest(coalesce(try_cast($s AS DOUBLE), -90), -90);
SET VARIABLE n = least(coalesce(try_cast($n AS DOUBLE), 90), 90);
SET VARIABLE near = getvariable('e') - getvariable('w') <= 25 AND getvariable('n') - getvariable('s') <= 25;
SET VARIABLE t0 = greatest(coalesce(try_cast($t0 AS TIMESTAMP), TIMESTAMP '2000-11-01'), TIMESTAMP '2000-11-01');
SET VARIABLE t1 = least(coalesce(try_cast($t1 AS TIMESTAMP), current_date + 1), current_date + 1);
SET VARIABLE files = (
  SELECT CASE WHEN getvariable('near') AND count(*) > 0
              THEN list(format('https://data.source.coop/portolan-mirrors/firms-catalog/detections/year={}/detections.parquet', y) ORDER BY y)
              ELSE ['https://data.source.coop/portolan-mirrors/firms-catalog/detections/year=2000/detections.parquet'] END
  FROM range(year(getvariable('t0')), year(getvariable('t1') - INTERVAL 1 MICROSECOND) + 1) AS t(y)
);
SELECT round(ST_Y(geometry), 4) AS latitude, round(ST_X(geometry), 4) AS longitude,
       frp, round(log10(greatest(frp, 0.1)), 2) AS frp_log,
       strftime(acq_datetime, '%Y-%m-%d %H:%M UTC') AS seen,
       satellite, CASE daynight WHEN 'N' THEN 'night' ELSE 'day' END AS daynight, confidence
FROM read_parquet(getvariable('files'))
WHERE getvariable('near')
  AND ST_Intersects_Extent(geometry, ST_MakeEnvelope(getvariable('w'), getvariable('s'), getvariable('e'), getvariable('n')))
  AND acq_datetime >= getvariable('t0') AND acq_datetime < getvariable('t1')
ORDER BY frp DESC
LIMIT 100000
